    /// Whether to sponsor this transaction via Gas Station. If false or unset, the EOA pays gas. A single call uses EIP-1559; multiple calls use EIP-7702 batch execution via Gas Station.
    public let sponsor: Bool?

    public init(
        caip2: String,
        calls: [v1EthCallParams],
        deadline: String? = nil,
        from: String,
        gasLimit: String? = nil,
        gasStationNonce: String? = nil,
        maxFeePerGas: String? = nil,
        maxPriorityFeePerGas: String? = nil,
        nonce: String? = nil,
        sponsor: Bool? = nil
    ) {
