public struct v1InvitationParams: Codable, Sendable {
    /// The User's permissible access method(s).
    public let accessType: v1AccessType
    /// The email address of the intended Invitation recipient.
    public let receiverUserEmail: String
    /// The name of the intended Invitation recipient.
    public let receiverUserName: String
    /// A list of tags assigned to the Invitation recipient. This field, if not needed, should be an empty array in your request body.
    public let receiverUserTags: [String]
    /// Unique identifier for the Sender of an Invitation.
    public let senderUserId: String

    public init(
        accessType: v1AccessType,
        receiverUserEmail: String,
        receiverUserName: String,
        receiverUserTags: [String],
        senderUserId: String
    ) {
        self.accessType = accessType
        self.receiverUserEmail = receiverUserEmail
        self.receiverUserName = receiverUserName
        self.receiverUserTags = receiverUserTags
        self.senderUserId = senderUserId
    }
}

public struct v1IpAllowlist: Codable, Sendable {
    /// Whether the IP allowlist is enabled. Only present for organization-level allowlists. Null for API key-level allowlists (presence of the allowlist implies enablement).
    public let enabled: Bool?
    /// Behavior when an error occurs during IP allowlist evaluation. Valid values: ALLOW, DENY. Defaults to DENY.
    public let onEvaluationError: String?
    /// Unique identifier for the organization this allowlist belongs to.
    public let organizationId: String
    /// Public key of the API key this allowlist applies to. Null means the allowlist applies to the entire organization.
    public let publicKey: String?
    /// List of IP allowlist rules with their metadata.
    public let rules: [v1IpAllowlistRule]

    public init(
        enabled: Bool? = nil,
        onEvaluationError: String? = nil,
        organizationId: String,
        publicKey: String? = nil,
        rules: [v1IpAllowlistRule]
    ) {
        self.enabled = enabled
        self.onEvaluationError = onEvaluationError
        self.organizationId = organizationId
        self.publicKey = publicKey
        self.rules = rules
    }
}

public struct v1IpAllowlistIntentRule: Codable, Sendable {
    /// CIDR block (e.g., '192.168.1.0/24', '2001:db8::/32').
    public let cidr: String
    /// Optional human-readable label for this rule (e.g., 'Office VPN').
    public let label: String?

    public init(
        cidr: String,
        label: String? = nil
    ) {
        self.cidr = cidr
        self.label = label
    }
}

public struct v1IpAllowlistRule: Codable, Sendable {
    /// CIDR block (e.g., '192.168.1.0/24').
    public let cidr: String
    /// Creation timestamp as millisecond epoch string.
    public let createdAt: String?
    /// Optional human-readable label for this rule.
    public let label: String?

    public init(
        cidr: String,
        createdAt: String? = nil,
        label: String? = nil
    ) {
        self.cidr = cidr
        self.createdAt = createdAt
        self.label = label
    }
}

public struct v1ListEarnEnabledVaultsRequest: Codable, Sendable {
    /// Optional filter: only return enabled vaults whose underlying asset matches this CAIP-19 asset ID (e.g. 'eip155:8453/erc20:0x833589...'). The chain is taken from the CAIP-19 identifier.
